function header(page){$('#header').innerHTML=`<a class="brand" href="#today">NUS Career Space</a><nav aria-label="Main navigation">${['Today','Jobs','Interviews','Job Events','Profile'].map(t=>`<a href="#${t.toLowerCase().replace(' ','-')}" class="${page===t.toLowerCase().replace(' ','-')?'active':''}">${t}</a>`).join('')}<button class="nav-chat" id="chat-toggle" aria-controls="career-chat" aria-expanded="${chatOpen}"><span aria-hidden="true">✦</span> AI Chat</button></nav><a class="capture" href="#plugin">Plugin demo ↗</a><button class="avatar" id="account-toggle" aria-label="Account menu" aria-expanded="false">ZY</button>`;$('#chat-toggle').onclick=()=>toggleChat();$('#account-toggle').onclick=toggleAccountMenu;}
