function interviewResearch(){let state=activeInterview().researchState||'idle';return `<div class="interview-questions"><div class="row between"><h3>Questions & answer ideas</h3><span class="pill attention">AI PREVIEW</span></div>${state==='idle'?`<button data-action="collect-interview">Find likely questions →</button><small class="block-note">Demo · No live web search</small>`:state==='loading'?'<div class="row"><div class="spinner" style="margin:0;width:20px;height:20px"></div>Preparing question & answer cards…</div>':`${questionAnswers()}<details><summary>Sources & context</summary><p class="footnote">Illustrative prompts, not verified company interview reports. Use these sources to research the role.</p>${ext('https://careers.nus.edu.sg/NUS/','NUS career resources')}</details><small>Demo suggestions · Keep your own wording</small>`}</div>`}
function calendarPopover(anchor){document.querySelector('.calendar-popover')?.remove();let key=anchor.dataset.date,entries=calendarEntries().filter(e=>e.date===key),entry=entries.find(e=>e.id===anchor.dataset.entry),pop=document.createElement('div');pop.className='calendar-popover';pop.setAttribute('role','dialog');pop.setAttribute('aria-label','Calendar event details');let content=entry?`<span class="badge ${entry.type}">${entry.type==='Event'?'Saved event':entry.type}</span><h3 class="sectiongap">${esc(entry.title||entry.company)}</h3>${entry.company&&entry.title?`<p>${esc(entry.company)}</p>`:''}<div class="calendar-facts"><span>Time</span><b>${entry.time?esc(entry.time)+' SGT':'All day'}</b><span>Location</span><b>${esc(entry.location||'Application record')}</b>${entry.round?`<span>Round</span><b>${esc(entry.round)}</b>`:''}</div><button class="primary wide sectiongap" data-open-entry="${esc(entry.id)}">${entry.type==='Interview'?'Prepare for interview →':entry.type==='Event'?'View job events →':'View application →'}</button>${entry.type==='Event'?`<button class="quiet wide sectiongap" data-unsave-calendar="${entry.eventId}">Remove from saved events</button>`:''}`:entries.length?entries.map(e=>`<button class="calendar-entry-row" data-open-entry="${esc(e.id)}"><span class="badge ${e.type}">${e.type}</span><b>${esc(e.title||e.company)}</b><small>${esc(e.time||'All day')}</small></button>`).join(''):'<h3 class="sectiongap">No scheduled events</h3><small>Your calendar is clear for this day.</small>';pop.innerHTML=`<div class="row between" style="margin-bottom:16px"><span class="label">${new Date(key+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</span><button class="close" aria-label="Close event">×</button></div>${content}`;document.body.append(pop);let r=anchor.getBoundingClientRect(),w=pop.offsetWidth,x=r.right+12;if(x+w>innerWidth-12)x=Math.max(12,r.left-w-12);pop.style.left=x+'px';pop.style.top=Math.max(12,Math.min(r.top,innerHeight-pop.offsetHeight-12))+'px';pop.querySelector('.close').onclick=()=>{pop.remove();anchor.focus()};pop.querySelectorAll('[data-open-entry]').forEach(b=>b.onclick=()=>{let e=entries.find(e=>e.id===b.dataset.openEntry);pop.remove();if(e.type==='Interview'){currentInterviewId=e.id;prepStep='home';location.hash='interviews';render()}else if(e.type==='Event'){eventOnly=true;eventTopics=[];eventSingapore=false;location.hash='job-events';render()}else{selected=data.jobs.find(j=>j.company===e.company)?.id;location.hash='jobs';render()}});pop.querySelector('[data-unsave-calendar]')?.addEventListener('click',e=>{data.savedEvents=data.savedEvents.filter(id=>id!==Number(e.target.dataset.unsaveCalendar));save();pop.remove();render();toast('Removed from calendar')});pop.querySelector('.close').focus();setTimeout(()=>{function outside(e){if(!pop.isConnected){document.removeEventListener('pointerdown',outside);return}if(!pop.contains(e.target)&&!anchor.contains(e.target)){pop.remove();document.removeEventListener('pointerdown',outside)}}document.addEventListener('pointerdown',outside)},0)}
function interviews(){let it=activeInterview(),selectedStories=it.stories.map(i=>({...stories[i],id:'saved-'+i,sample:true})),extra=it.extraStories||[];return `<div class="row between wrap"><h1>Interviews</h1><button class="primary" data-action="add-interview">+ Add interview</button></div><div class="interview-switcher" aria-label="Your interviews">${data.interviews.map(item=>`<button data-select-interview="${item.id}" class="${item.id===it.id?'active':''}"><b>${esc(item.company)}</b><span>${esc(item.title)}</span><small>${esc(item.date)} · ${esc(item.time)} SGT</small></button>`).join('')}</div><section class="card interview-document" data-interview-selectable><div class="interview-document-heading"><div><span class="label">${esc(it.date)} · ${esc(it.time)} SGT · ${esc(it.location)}</span><h2>${esc(it.company)} · ${esc(it.title)}</h2></div><span class="pill attention">${esc(it.round)}</span></div><div class="row between wrap"><h3>Relevant experiences</h3><div class="row"><button class="quiet" data-action="choose-experiences">Choose</button><button class="quiet" data-action="add-experience">+ Add experience</button></div></div><small class="selection-hint">Select text to ask AI.</small><div class="experience-list">${[...selectedStories,...extra].map(e=>`<article class="experience-note" data-experience-id="${esc(e.id)}"><div class="row between"><h3>${esc(e.title)}</h3><button class="quiet experience-ask" data-ask-experience="${esc(e.id)}">Ask AI ↗</button></div><small>${e.sample?'Example · ':''}${esc(e.tags||'My experience')}</small><p>${esc(e.text)}</p></article>`).join('')||'<div class="empty">Add an experience or choose one from your profile.</div>'}</div><label class="field sectiongap">My preparation notes<textarea id="interview-notes" placeholder="Your role, key decision, outcome…">${esc(it.prepNotes||'')}</textarea></label><small class="notes-saved" id="notes-saved">Saved in this browser</small><details class="sectiongap"><summary>Materials & practice</summary>${interviewFiles()}<div class="sectiongap">${ext('https://www.vmock.com/nus','Practise with VMock')}</div></details><details><summary>After the interview</summary><label class="field sectiongap">One thing to remember<textarea id="interview-review" placeholder="What would you change next time?">${esc(it.shortReflection||it.reflection?.change||'')}</textarea></label><small>Saved in this browser</small></details></section>`}
const eventData=[['28','OCT','Design Portfolio Clinic','Career workshop','Design','Portfolio feedback'],['30','OCT','Research Careers Panel','Employer panel','Research','Research interests'],['03','NOV','Internship Networking','Networking','Product','Singapore internships'],['05','NOV','Product Careers Session','Career talk','Product','Product interests'],['07','NOV','Interview Practice Lab','Workshop','Design','Upcoming interview'],['10','NOV','Technology Career Fair','Career fair','Engineering','Technology interests']];
function events(){let locations=['Singapore','Online','Singapore','Online','Singapore','Singapore'],list=eventData.map((e,i)=>({e,i,location:locations[i]})).filter(({e,i,location})=>(!eventOnly||data.savedEvents.includes(i))&&(!eventTopics.length||eventTopics.includes(e[4]))&&(!eventSingapore||location==='Singapore'));return `<div class="row between"><h1>Job Events</h1><button data-action="saved-events">${eventOnly?'Show all':'Saved events'}</button></div><div class="event-filters row wrap" aria-label="Event filters"><span class="label">Filter</span><button data-event-filter="all" aria-pressed="${!eventTopics.length&&!eventSingapore}" class="${!eventTopics.length&&!eventSingapore?'active':''}">All</button>${['Design','Research'].map(t=>`<button data-event-filter="${t}" aria-pressed="${eventTopics.includes(t)}" class="${eventTopics.includes(t)?'active':''}">${t}</button>`).join('')}<span class="filter-separator"></span><button data-event-filter="Singapore" aria-pressed="${eventSingapore}" class="${eventSingapore?'active':''}">Singapore</button><small>${list.length} events</small></div><div class="events">${list.map(({e,i,location})=>`<section class="card"><div class="row between"><div class="datebox"><small>${e[1]}</small><b>${e[0]}</b></div><span class="pill">${e[3]}</span></div><h3>${e[2]}</h3><div class="row wrap"><span class="pill">${e[4]}</span><small>${location}</small></div><div class="row wrap"><button data-event="${i}" class="${data.savedEvents.includes(i)?'primary':''}">${data.savedEvents.includes(i)?'✓ Saved':'Save event'}</button><button class="quiet" data-calendar-download="${i}">Export .ics ↗</button>${data.savedEvents.includes(i)?`<button class="quiet" data-view-event-calendar="${i}">View in calendar →</button>`:''}</div><small>Sample event · NUS Career Space demo</small></section>`).join('')||'<div class="card empty">No events match.<br><button data-action="clear-event-filters">Clear filters</button></div>'}</div>`}
function profile(){return `<div class="row between"><h1>Profile</h1><button class="primary" data-action="upload">Upload material +</button></div><div class="card row between" style="margin-bottom:24px"><div><h3>Zi Yean</h3><small>NUS student · Singapore</small></div></div><div class="profile">${['Resume','Portfolio'].map(t=>`<section class="card"><div class="row between"><h2>${t==='Resume'?'Resumes':'Portfolios'}</h2><small>${data.files.filter(f=>f.type===t).length} versions</small></div>${data.files.filter(f=>f.type===t).map((f)=>`<button class="file file-open row between" data-preview-file="${esc(f.id)}"><span><b>${esc(f.name)}</b><small>${esc(f.category)} · ${f.uploaded?'Browser-local file':f.date+' · Sample'}</small></span><span class="preview-arrow" aria-hidden="true">↗</span></button>`).join('')}</section>`).join('')}</div><details class="card sectiongap"><summary>My experiences <small>· ${stories.length} stories</small></summary><div class="profile sectiongap">${stories.map(s=>`<section class="card soft"><h3>${s.title}</h3><span class="pill">${s.tags}</span><p class="muted sectiongap">${s.text}</p></section>`).join('')}</div></details><details class="card sectiongap"><summary>Experience & learning <small>· Optional</small></summary><p class="sectiongap">Weekly reading → One useful action</p><label class="field">Your reading note<textarea id="readingnote" placeholder="One idea you want to use…">${esc(data.reading||'')}</textarea></label><button class="sectiongap" data-action="reading">Save note & add a task</button><p class="footnote">Your note stays in Profile. A follow-up appears in Today.</p></details>`}
function plugin(){return `<div class="row between" style="margin-bottom:24px"><span class="demo">PLUGIN SIMULATION · Sample employer page</span><a href="#today">Open Workspace →</a></div><div class="plugin-scene"><article class="posting"><div class="row between"><span class="serif" style="font-size:28px">figma</span><small>Careers / Design</small></div><h1>Product Designer Intern</h1><span class="pill">Singapore · Internship</span><hr class="divider"><h3>Design how people create together.</h3><p class="muted">Collaborate with designers, researchers and engineers to build thoughtful product experiences.</p><ul><li>Explore user needs and interaction patterns</li><li>Prototype and test product ideas</li><li>Communicate design decisions clearly</li></ul><p class="footnote">Illustrative JD for this demo. This is not a live vacancy.</p></article><section class="plugin"><div class="row between"><b>NUS Career Space</b><a href="#today"><small>Workspace ↗</small></a></div><hr class="divider">${pluginContent()}</section></div>`}
function pluginContent(){if(pluginStage==='loading')return '<div class="spinner"></div><h2>Reading this page</h2><p class="muted">Role · Category · Best-fit materials</p><small>Demo AI preview</small>';if(pluginStage==='saved')return `<div class="success">✓</div><h2>Opportunity saved</h2><p>${esc(draft.title)}</p><small>${esc(draft.company)} · ${esc(draft.category)}</small><button class="primary wide sectiongap" data-action="workspace">Open Workspace →</button><button class="wide sectiongap" data-action="capture-again">Save another role</button>`;if(pluginStage==='start')return `<span class="pill">READY TO READ</span><h2>Save opportunity</h2><p class="muted">Read the role and match your materials.</p><button class="primary wide" data-action="read">Read this page</button><details class="sectiongap"><summary>Use another JD</summary><label class="field sectiongap">Job description<textarea id="customjd" placeholder="Role: …&#10;Company: …&#10;Location: …&#10;Description: …"></textarea></label><button class="wide sectiongap" data-action="read-custom">Read pasted JD</button></details>`;return `<span class="pill">✓ READ FROM THIS PAGE</span><h2>Save opportunity</h2><section class="card"><label class="field">Position<input type="text" id="draft-title" value="${esc(draft.title)}"></label><label class="field sectiongap">Company<input type="text" id="draft-company" value="${esc(draft.company)}"></label><label class="field sectiongap">${draft.manual?'Choose category · Could not classify':'AI category · Review or correct'}<select id="draft-category">${cats.map(c=>`<option value="${esc(c)}" ${draft.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></section><div class="label sectiongap">Priority</div><div class="seg">${['Low','Medium','High'].map(v=>`<button data-priority="${v}" class="${pluginPriority===v?'active':''}">${v}</button>`).join('')}</div><section class="card sectiongap"><span class="pill attention">AI FILE MATCH · PREVIEW</span>${['Resume','Portfolio'].map(t=>`<label class="field sectiongap">${t}<select id="draft-${t.toLowerCase()}">${data.files.filter(f=>f.type===t).map(f=>`<option ${f.category===draft.category?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label>`).join('')}</section><button class="primary wide sectiongap" data-action="save-job">Confirm files & save</button><p class="footnote">Source link included · Review before saving</p>`}
function bindTasks(root=document){root.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{data.tasks[el.dataset.task]=el.checked;save()})}
function bind(){bindTasks();bindCustomControls();document.querySelectorAll('[data-job]').forEach(el=>{el.onclick=()=>{selected=+el.dataset.job;render()};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}});document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{view=el.dataset.view;render()});document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{let arr=filters[el.dataset.filter];filters[el.dataset.filter]=el.checked?[...arr,el.value]:arr.filter(v=>v!==el.value);render()});$('#jobsearch')?.addEventListener('input',e=>{let pos=e.target.selectionStart;query=e.target.value;render();$('#jobsearch').focus();$('#jobsearch').setSelectionRange(pos,pos)});document.querySelectorAll('[data-step]').forEach(el=>el.onclick=e=>{e.preventDefault();prepStep=el.dataset.step;render();scrollTo(0,0)});document.querySelectorAll('[data-story]').forEach(el=>el.onchange=()=>{let i=+el.dataset.story;activeInterview().stories=el.checked?[...activeInterview().stories,i]:activeInterview().stories.filter(v=>v!==i);save();render()});document.querySelectorAll('[data-material]').forEach(el=>el.onchange=()=>{activeInterview()['interview'+el.dataset.material]=el.value;save()});$('#reflection')?.addEventListener('submit',e=>{e.preventDefault();activeInterview().reflection=Object.fromEntries(new FormData(e.target));save();toast('Reflection saved. Ready for next time.');render()});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-event]').forEach(el=>el.onclick=()=>{let i=+el.dataset.event;let removing=data.savedEvents.includes(i);data.savedEvents=removing?data.savedEvents.filter(n=>n!==i):[...data.savedEvents,i];save();render();toast(removing?'Removed from calendar':'Saved to your calendar')});document.querySelectorAll('[data-calendar-download]').forEach(el=>el.onclick=()=>downloadEvent(+el.dataset.calendarDownload));document.querySelectorAll('[data-calendar]').forEach(el=>el.onclick=()=>calendarPopover(el));document.querySelectorAll('[data-priority]').forEach(el=>el.onclick=()=>{captureDraft();pluginPriority=el.dataset.priority;render()});$('#draft-category')?.addEventListener('change',()=>{captureDraft();render()});}
function captureDraft(){if($('#draft-title')){draft.title=$('#draft-title').value;draft.company=$('#draft-company').value;draft.category=$('#draft-category').value;}}
function action(a){if(a==='open-interview'){location.hash='interviews';render();return}if(a==='toggle-task'){let form=$('#add-task-form');form.hidden=!form.hidden;if(!form.hidden)$('#new-task').focus();return}if(a==='news-interests')return chooseNewsInterests();if(a==='choose-experiences')return chooseExperiences();if(a==='add-experience')return addExperience();if(a==='add-category')return categoryDialog();if(a==='add-interview')return addInterview();if(a==='clear-event-filters'){eventTopics=[];eventSingapore=false;eventOnly=false;render();return}if(a==='collect-interview'){let target=activeInterview();target.researchState='loading';save();render();setTimeout(()=>{target.researchState='ready';save();if(activeInterview().id===target.id)render()},1200)}if(a==='research-prepare'){activeInterview().researchApproved=true;save();prepStep='choose';render();scrollTo(0,0)} if(a==='clearfilters'){filters={Category:[],Location:[],Progress:[]};query='';render()}if(a==='generate'){let target=activeInterview();document.querySelectorAll('[data-material]').forEach(el=>activeInterview()['interview'+el.dataset.material]=el.value);save();prepStep='loading';location.hash='interviews';render();setTimeout(()=>{target.outline=true;save();if(activeInterview().id===target.id){prepStep='outline';render();scrollTo(0,0)}},1100)}if(a==='outline'){prepStep='outline';location.hash='interviews';render()}if(a==='saved-events'){eventOnly=!eventOnly;render()}if(a==='upload')upload();if(a==='reading'){data.reading=$('#readingnote').value.trim();if(!data.reading)return toast('Add a note first.');data.tasks['reading-action']=false;save();toast('Note saved. Follow-up added to Today.')}if(a==='read'||a==='read-custom'){let text=a==='read-custom'?$('#customjd').value.trim():'';if(a==='read-custom'&&!text)return toast('Paste a JD first.');draft={title:'Product Designer Intern',company:'Figma',category:'Design',location:'Singapore',url:'https://www.figma.com/careers/'};if(text){let get=k=>text.match(new RegExp('(?:^|\\n)'+k+'\\s*:\\s*([^\\n]+)','i'))?.[1]?.trim();let cat=/research/i.test(text)?'Research':/engineer|developer/i.test(text)?'Engineering':/design/i.test(text)?'Design':/product/i.test(text)?'Product':null;draft={title:get('Role')||get('Position')||text.split('\n')[0].slice(0,90),company:get('Company')||'Company',location:get('Location')||'Singapore',category:cat||'Design',manual:!cat,url:'https://careers.nus.edu.sg/NUS/'};}if(!cats.includes(draft.category)){draft.category=cats[0];draft.manual=true}pluginStage='loading';render();setTimeout(()=>{pluginStage='ready';render()},1000)}if(a==='save-job'){captureDraft();if(!draft.title.trim()||!draft.company.trim())return toast('Add a position and company.');let existing=data.jobs.find(j=>j.company===draft.company&&j.title===draft.title);let j={...draft,id:existing?.id||Date.now(),status:existing?.status||'Saved',priority:pluginPriority,resume:$('#draft-resume').value,portfolio:$('#draft-portfolio').value};data.jobs=existing?data.jobs.map(old=>old.id===j.id?j:old):[j,...data.jobs];save();pluginStage='saved';render()}if(a==='workspace'){selected=null;location.hash='jobs';toast('Saved role is in your Workspace.')}if(a==='capture-again'){pluginStage='start';render()}if(a==='reset'){if(confirm('Reset this demo? Your browser-local notes and uploaded material names will be removed.')){profilePreviewId=null;destroyFilePreview();chatContext=null;data=seed();normaliseData();currentInterviewId=data.interviews[0].id;eventTopics=[];eventSingapore=false;save();selected=null;pluginStage='start';prepStep='home';filters={Category:[],Location:[],Progress:[]};query='';render();toast('Demo reset')}}}
function upload(){let dialog=document.createElement('dialog');dialog.setAttribute('aria-label','Add material');dialog.innerHTML=`<div class="row between"><h2>Add material</h2><button class="close" type="button" aria-label="Close upload">×</button></div><form class="uploadform"><label class="field">File<input type="file" name="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.png,.jpg,.jpeg" required></label><label class="field">Display name<input type="text" name="name" maxlength="120" placeholder="Design resume · v4" required></label><div class="formgrid"><label class="field">Type<select name="type"><option>Resume</option><option>Portfolio</option></select></label><label class="field">Category<select name="category">${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><small>Saved only in this browser. PDF and image files can be previewed. Nothing is uploaded to a server.</small><p class="form-error" role="alert"></p><button class="primary">Add material</button></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();let form=new FormData(e.target),file=form.get('file'),name=form.get('name').trim(),button=e.target.querySelector('[type=submit],button.primary');if(!name)return;button.disabled=true;let item={id:'material-'+Date.now(),name,type:form.get('type'),category:form.get('category'),filename:file.name,mime:file.type,uploaded:true};try{await localFileStore('put',item.id,file);item.hasBlob=true;data.files.push(item);save();dialog.close();render();toast('Material saved in this browser')}catch{button.disabled=false;dialog.querySelector('.form-error').textContent='Browser file storage is unavailable. Try a regular browser window.'}}}
function downloadEvent(i){let e=eventData[i],d='2026'+(e[1]==='OCT'?'10':'11')+e[0];let ics=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//NUS Career Space Demo//EN\r\nBEGIN:VEVENT\r\nUID:demo-${i}@nus-career-space.local\r\nDTSTAMP:20261025T000000Z\r\nDTSTART;VALUE=DATE:${d}\r\nSUMMARY:[Demo] ${e[2]}\r\nDESCRIPTION:Illustrative event for the NUS Career Space prototype.\r\nEND:VEVENT\r\nEND:VCALENDAR`;let u=URL.createObjectURL(new Blob([ics],{type:'text/calendar'})),a=document.createElement('a');a.href=u;a.download='demo-event.ics';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function toggleChat(force){chatOpen=typeof force==='boolean'?force:!chatOpen;let toggle=$('#chat-toggle');toggle?.setAttribute('aria-expanded',String(chatOpen));toggle?.classList.toggle('active',chatOpen);if(chatOpen){chatFocusReturn=document.activeElement;renderChat();$('#chat-question').focus()}else{document.querySelector('#career-chat')?.remove();chatFocusReturn?.isConnected?chatFocusReturn.focus():toggle?.focus()}}
function chatSuggestions(){let route=location.hash.slice(1)||'today';return route==='interviews'?['How do I prepare for my interview?','Which experience should I use?','Where can I practise?']:route==='profile'||route==='plugin'?['Which resume should I use?','How do I save a job?','What should I do today?']:['What should I do today?','How do I prepare for my interview?','Which resume should I use?']}
function renderChat(){let panel=$('#career-chat');if(!panel){panel=document.createElement('aside');panel.id='career-chat';panel.className='chat-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Career AI Chat');document.body.append(panel)}panel.innerHTML=`<div class="chat-heading"><div><h2>AI Chat</h2><small>Demo assistant · Guided replies</small></div><button class="close" id="close-chat" aria-label="Close AI Chat">×</button></div><div class="chat-body" id="chat-messages" role="log" aria-label="Conversation" aria-live="polite">${chatMessages.length?chatMessages.map(m=>`<div class="chat-message ${m.role}"><span class="label">${m.role==='user'?'You':'Career Space'}</span>${m.context?`<blockquote class="chat-quote">${esc(m.context.text)}</blockquote>`:''}<p>${esc(m.text)}</p>${m.actions?`<div class="chat-actions">${m.actions.map(a=>a.go==='advisor'?`<a class="advisor-link" href="https://www.nus.edu.sg/cfg/students/career-ready/career-advisory" target="_blank" rel="noopener noreferrer">Speak to a NUS Career Advisor ↗</a>`:`<button data-chat-go="${a.go}">${a.label} →</button>`).join('')}</div>`:''}</div>`).join(''):`<div class="chat-empty"><span class="chat-spark" aria-hidden="true">✦</span><h3>What do you need?</h3><p class="muted">Jobs · Materials · Interview prep</p><div class="chat-suggestions">${chatSuggestions().map(q=>`<button data-chat-question="${q}">${q} ↗</button>`).join('')}</div></div>`}</div><form class="chat-compose" id="chat-form"><label for="chat-question" class="label">Your question</label>${chatContext?`<div class="chat-context"><span>Selected · ${esc(chatContext.company)}</span><button type="button" id="remove-chat-context" aria-label="Remove selected text context">×</button><p>${esc(chatContext.text.slice(0,240))}${chatContext.text.length>240?'…':''}</p></div>`:''}<div class="chat-input-row"><textarea id="chat-question" name="question" rows="2" maxlength="1500" placeholder="Ask a question…" required>${esc(chatDraft)}</textarea><button class="primary" aria-label="Send question">↑</button></div><div class="row between"><small>No live AI or web search connected</small>${chatMessages.length?'<button class="quiet" type="button" id="clear-chat">Clear chat</button>':''}</div></form>`;$('#close-chat').onclick=()=>toggleChat(false);$('#remove-chat-context')?.addEventListener('click',()=>{chatContext=null;renderChat();$('#chat-question').focus()});$('#chat-question').oninput=e=>chatDraft=e.target.value;$('#chat-form').onsubmit=e=>{e.preventDefault();sendChat($('#chat-question').value)};$('#chat-question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendChat(e.target.value)}};$('#clear-chat')?.addEventListener('click',()=>{chatMessages=[];chatDraft='';chatContext=null;renderChat();$('#chat-question').focus()});panel.querySelectorAll('[data-chat-question]').forEach(b=>b.onclick=()=>sendChat(b.dataset.chatQuestion));panel.querySelectorAll('[data-chat-go]').forEach(b=>b.onclick=()=>{let go=b.dataset.chatGo;if(go==='prepare'){prepStep='home';location.hash='interviews';render()}else if(go==='research'){prepStep='home';location.hash='interviews';render()}else location.hash=go;toggleChat(false)});let log=$('#chat-messages');log.scrollTop=log.scrollHeight}
function sendChat(raw){let text=raw.trim();if(!text)return;chatDraft='';let q=text.toLowerCase(),answer,actions=[];if(/advisor|human|person|人工|老师|顾问|签证|visa|salary|薪资|offer|不对|没帮助|不懂|cannot|can't|not helpful/.test(q)){answer='This needs individual advice. Speak to a NUS Career Advisor through the official appointment page.\nYour chat is not sent automatically. School sign-in may be required.';actions=[{label:'Speak to a NUS Career Advisor',go:'advisor'}]}else if(chatContext){answer='For '+chatContext.company+' · '+chatContext.title+':\n\nKeep this experience in your own words. Make three things clear:\n• Your specific responsibility\n• One decision you made and why\n• What changed, using only evidence you have\n\nTry: “I was responsible for [role]. I chose [action] because [reason]. The result was [what happened].”\n\nDemo guidance · Fill in the details yourself.';actions=[]}else if(/resume|portfolio|material|简历|作品集|材料/.test(q)){let category=location.hash==='#interviews'?(data.jobs.find(j=>j.id===activeInterview().jobId)?.category||'Product'):selected?data.jobs.find(j=>j.id===selected)?.category:draft?.category||'Design',files=data.files.filter(f=>f.category===category);answer=`For ${category.toLowerCase()} roles, review these saved materials:\n${files.map(f=>'• '+f.name).join('\n')||'No matching files yet.'}\nThis demo matches by category. Confirm the content against the JD.`;actions=[{label:'Review profile',go:'profile'}]}else if(/experience|story|stories|经历|故事/.test(q)){answer='For collaboration questions: Getting a team unstuck.\nFor research or problem framing: Finding the real problem.\nChoose a story you can explain in your own words.';actions=[{label:'Choose experiences',go:'prepare'}]}else if(/vmock|practi[cs]|模拟|练习/.test(q)){answer='Use the VMock entry in Interviews for mock interview practice and detailed feedback. Career Space helps you choose stories, organise materials and reflect afterwards.';actions=[{label:'Open Interviews',go:'research'}]}else if(/interview|面试/.test(q)){answer=activeInterview().company+' · '+activeInterview().title+'\n'+activeInterview().date+' · '+activeInterview().time+' SGT\n\nReview your relevant experiences, add your own notes, and select any text to discuss it in AI Chat.\nThe demo provides guided replies rather than live AI.';actions=[{label:'Open interview notes',go:'research'},{label:'Prepare materials',go:'prepare'}]}else if(/save|capture|plugin|保存|收集/.test(q)){answer='Plugin demo → Read this page → Review the category and recommended materials → Confirm files & save.\nThe saved role appears in Jobs. JD reading is simulated in this demo.';actions=[{label:'Open Plugin',go:'plugin'}]}else if(/today|task|next|今天|任务|下一步/.test(q)){let pending=[!data.tasks['resume-review']?'Resume review · Figma':null,!data.tasks['follow-up']?'Follow-up · Grab':null,data.reading&&!data.tasks['reading-action']?'Use one idea from your reading':null].filter(Boolean);answer=pending.length?'Your remaining actions:\n'+pending.map(t=>'□ '+t).join('\n'):'Your listed actions are complete. Review your interview materials when you are ready.';actions=[{label:'Open Today',go:'today'}]}else if(/job|role|filter|工作|职位|筛选/.test(q)){answer=`You have ${data.jobs.length} saved sample roles across ${cats.map(esc).join(', ')}. Use the visible filters for category, location and progress, then open a role in the right-side panel.`;actions=[{label:'Browse jobs',go:'jobs'}]}else if(/event|活动/.test(q)){answer=`You have ${data.savedEvents.length} saved sample events. Job Events includes portfolio clinics, career panels and networking. Dates and recommendations are illustrative.`;actions=[{label:'Browse events',go:'job-events'}]}else{answer='I cannot answer this reliably in the demo. A NUS Career Advisor can help with your specific situation.\nOpen the official page to request an appointment. Your conversation will not be sent automatically.';actions=[{label:'Speak to a NUS Career Advisor',go:'advisor'}]}chatMessages.push({role:'user',text,context:chatContext?{...chatContext}:null},{role:'assistant',text:answer,actions});renderChat();$('#chat-question').focus()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&chatOpen){e.preventDefault();toggleChat(false)}});
let currentInterviewId=null,eventTopics=[],eventSingapore=false;
function normaliseData(){if(!data.customTasks)data.customTasks=[];if(!data.newsInterests)data.newsInterests=['Design','Research'];data.files.forEach((f,i)=>{if(!f.id)f.id='material-seed-'+i});cats=data.categories?.length?[...data.categories]:[...BASE_CATS];data.categories=cats;if(!data.interviews?.length)data.interviews=[{id:'shopee-demo',company:'Shopee',title:'Associate Product Manager',jobId:13,date:'2026-10-26',time:'14:00',location:'Online',round:'Round 1',stories:data.stories||[0,1],outline:!!data.outline,reflection:data.reflection||null,researchState:data.researchState==='ready'?'ready':'idle',researchApproved:!!data.researchApproved,interviewResume:data.interviewResume||null,interviewPortfolio:data.interviewPortfolio||null}];data.interviews.forEach(it=>{if(!it.stories)it.stories=[];if(it.researchState==='loading')it.researchState='idle'})}
function activeInterview(){return data.interviews?.find(it=>it.id===currentInterviewId)||data.interviews?.[0]||{stories:[0,1]}}
function formDialog(title,body,onSubmit){const dialog=document.createElement('dialog');dialog.setAttribute('aria-label',title);dialog.innerHTML=`<div class="row between"><h2>${title}</h2><button class="close" type="button" aria-label="Close dialog">×</button></div><form class="uploadform">${body}<p class="form-error" role="alert"></p><button class="primary" type="submit">Save</button></form>`;document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const err=onSubmit(new FormData(e.target));if(err){dialog.querySelector('.form-error').textContent=err;return}dialog.close();save();render()};dialog.showModal();return dialog}
function categoryDialog(index){let old=cats[index];formDialog(old?'Rename category':'Add category',`<label class="field">Category name<input name="name" type="text" maxlength="36" value="${esc(old||'')}" required placeholder="e.g. Strategy"></label>`,form=>{let name=form.get('name').trim();if(!name)return 'Enter a category name.';if(cats.some((c,i)=>c.toLowerCase()===name.toLowerCase()&&i!==index))return 'That category already exists.';if(old){cats[index]=name;data.jobs.forEach(j=>{if(j.category===old)j.category=name});data.files.forEach(f=>{if(f.category===old)f.category=name});filters.Category=filters.Category.map(c=>c===old?name:c);if(draft?.category===old)draft.category=name}else cats.push(name);data.categories=[...cats];toast(old?'Category renamed':'Category added')})}
function moveJob(id,category){let j=data.jobs.find(j=>j.id===Number(id));if(!j||!cats.includes(category)||j.category===category)return;j.category=category;save();render();toast('Moved to '+category)}
function bindJobMoves(root=document){root.querySelectorAll('[data-move-job]').forEach(el=>{el.onclick=e=>e.stopPropagation();el.onchange=()=>moveJob(el.dataset.moveJob,el.value)})}
function bindCustomControls(){bindJobMoves();document.querySelectorAll('[data-delete-job]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();deleteJob(Number(b.dataset.deleteJob))});$('#add-task-form')?.addEventListener('submit',e=>{e.preventDefault();let title=$('#new-task').value.trim();if(!title)return;addCustomTask(title);render();$('#add-task-form').hidden=false;$('#new-task').focus()});document.querySelectorAll('[data-remove-task]').forEach(b=>b.onclick=()=>{data.customTasks=data.customTasks.filter(t=>t.id!==b.dataset.removeTask);delete data.tasks['custom-'+b.dataset.removeTask];save();render()});document.querySelectorAll('[data-news-task]').forEach(b=>b.onclick=()=>{addCustomTask(newsItems[+b.dataset.newsTask].apply);render()});document.querySelectorAll('[data-ask-experience]').forEach(b=>b.onclick=()=>{let it=activeInterview(),e=b.dataset.askExperience.startsWith('saved-')?stories[+b.dataset.askExperience.slice(6)]:(it.extraStories||[]).find(e=>e.id===b.dataset.askExperience);if(e)askAboutExperience(e.title+'\n'+e.text)});$('#interview-notes')?.addEventListener('input',e=>{activeInterview().prepNotes=e.target.value;save();$('#notes-saved').textContent='Saved'});$('#interview-review')?.addEventListener('input',e=>{activeInterview().shortReflection=e.target.value;save()});document.querySelectorAll('[data-preview-file]').forEach(b=>b.onclick=()=>{previewReturn=b;profilePreviewId=b.dataset.previewFile;render()});document.querySelectorAll('[data-calendar-month]').forEach(b=>b.onclick=()=>{document.querySelector('.calendar-popover')?.remove();let change=+b.dataset.calendarMonth;if(!change)calendarMonth='2026-10';else{let d=new Date(calendarMonth+'-01T12:00:00');d.setMonth(d.getMonth()+change);calendarMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}render()});document.querySelectorAll('[data-view-event-calendar]').forEach(b=>b.onclick=()=>{let ev=eventData[+b.dataset.viewEventCalendar];calendarMonth='2026-'+(ev[1]==='OCT'?'10':'11');location.hash='today';render()});document.querySelectorAll('[data-rename-category]').forEach(el=>el.onclick=()=>categoryDialog(+el.dataset.renameCategory));document.querySelectorAll('[data-drag-job]').forEach(el=>{el.ondragstart=e=>{if(e.target.closest('select')){e.preventDefault();return}e.dataTransfer.setData('text/plain',el.dataset.dragJob);e.dataTransfer.effectAllowed='move';el.classList.add('dragging')};el.ondragend=()=>el.classList.remove('dragging')});document.querySelectorAll('[data-drop-category]').forEach(el=>{el.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';el.classList.add('drag-over')};el.ondragleave=e=>{if(!el.contains(e.relatedTarget))el.classList.remove('drag-over')};el.ondrop=e=>{e.preventDefault();el.classList.remove('drag-over');moveJob(e.dataTransfer.getData('text/plain'),cats[+el.dataset.dropCategory])}});document.querySelectorAll('[data-select-interview]').forEach(el=>el.onclick=()=>{currentInterviewId=el.dataset.selectInterview;prepStep='home';render()});document.querySelectorAll('[data-event-filter]').forEach(el=>el.onclick=()=>{let f=el.dataset.eventFilter;if(f==='all'){eventTopics=[];eventSingapore=false}else if(f==='Singapore')eventSingapore=!eventSingapore;else eventTopics=eventTopics.includes(f)?eventTopics.filter(t=>t!==f):[...eventTopics,f];render()})}
function addInterview(){let dialog=formDialog('Add interview',`<label class="field">Link to a saved job (optional)<select name="jobId"><option value="">Enter manually</option>${data.jobs.map(j=>`<option value="${j.id}">${esc(j.company)} · ${esc(j.title)}</option>`).join('')}</select></label><div class="formgrid"><label class="field">Company<input type="text" name="company" maxlength="80" required></label><label class="field">Position<input type="text" name="title" maxlength="120" required></label><label class="field">Date<input type="date" name="date" required></label><label class="field">Time · SGT<input type="time" name="time" required></label><label class="field">Location / meeting details<input type="text" name="location" placeholder="Online / campus / office" maxlength="160" required></label><label class="field">Round<input type="text" name="round" value="Round 1" maxlength="60" required></label></div><small>Saved in this browser. No invitations are sent.</small>`,form=>{const values=Object.fromEntries(form);for(const k of ['company','title','date','time','location','round'])if(!values[k].trim())return 'Complete all required fields.';let jobId=Number(values.jobId)||null,it={...values,jobId,id:'interview-'+Date.now(),company:values.company.trim(),title:values.title.trim(),stories:[],researchState:'idle',outline:false,reflection:null};data.interviews.push(it);currentInterviewId=it.id;prepStep='home';let j=data.jobs.find(j=>j.id===jobId);if(j)j.status='Interview';toast('Interview added')});dialog.querySelector('[name=jobId]').onchange=e=>{let j=data.jobs.find(j=>j.id===Number(e.target.value));if(j){dialog.querySelector('[name=company]').value=j.company;dialog.querySelector('[name=title]').value=j.title}}}
function localFileStore(mode,key,file){return new Promise((resolve,reject)=>{let request=indexedDB.open('nus-career-local-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onerror=()=>reject(request.error);request.onsuccess=()=>{let db=request.result,tx=db.transaction('files',mode==='put'?'readwrite':'readonly'),store=tx.objectStore('files'),op=mode==='put'?store.put(file,key):store.get(key);op.onerror=()=>{db.close();reject(op.error)};tx.oncomplete=()=>{let result=op.result;db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)}}})}
function destroyFilePreview(){document.querySelector('.file-preview-panel')?.remove();if(previewObjectUrl){URL.revokeObjectURL(previewObjectUrl);previewObjectUrl=null}}
function closeFilePreview(){profilePreviewId=null;destroyFilePreview();render();document.querySelector(`[data-preview-file="${previewReturn?.dataset.previewFile}"]`)?.focus()}
function sampleResume(f){if(f.type==='Portfolio')return `<article class="resume-paper"><div class="resume-sample-label">SAMPLE PORTFOLIO · DEMO CONTENT</div><h2>Selected work</h2><p class="resume-subtitle">${esc(f.name)}</p><hr><h3>User research & problem framing</h3><p>Example case study · Understand the context, synthesise observations and define the problem.</p><div class="portfolio-placeholder">Research notes → Insights → Design direction</div><h3>Interaction design</h3><p>Example case study · Explore a flow, prototype it and use feedback to guide the next iteration.</p><div class="portfolio-placeholder">Sketch → Prototype → Iterate</div><footer>Illustrative portfolio layout, not a personal project document</footer></article>`;let research=/research/i.test(f.name),product=/product/i.test(f.name),focus=research?'UX Research':product?'Product Management':'Product & Interaction Design';return `<article class="resume-paper" aria-label="Sample resume page"><div class="resume-sample-label">SAMPLE RESUME · DEMO CONTENT</div><h2>Zi Yean</h2><p class="resume-subtitle">${focus} · Singapore</p><hr><h3>Profile</h3><p>NUS student exploring ${focus.toLowerCase()}. Interested in turning research into clear, useful product experiences.</p><h3>Education</h3><div class="resume-item"><b>National University of Singapore</b><span>Current student · Demonstration profile</span></div><h3>Selected experience</h3><div class="resume-item"><b>${research?'User research & problem framing':product?'Product decisions & collaboration':'Interaction design project'}</b><span>Course project · Example experience</span><ul><li>${research?'Explored user needs through interviews and synthesis.':product?'Helped the team clarify priorities and compare possible directions.':'Explored a user problem through sketches and interaction prototypes.'}</li><li>${research?'Translated patterns into a clearer problem definition.':product?'Connected user feedback with decisions about the next iteration.':'Used feedback to revise the flow and explain design choices.'}</li></ul></div><div class="resume-item"><b>Team collaboration project</b><span>Course project · Example experience</span><ul><li>Clarified responsibilities and helped move a shared decision forward.</li><li>Documented the process and reflected on the next improvement.</li></ul></div><h3>Skills</h3><p>${research?'Interview planning · Research synthesis · Usability testing':product?'Problem framing · Prioritisation · Stakeholder communication':'Interaction design · Prototyping · User research · Figma'}</p><footer>${esc(f.name)} · Illustrative layout, not a verified personal resume</footer></article>`}
async function renderPdfPages(file,container){let pdf;try{if(location.protocol==='file:'){container.innerHTML=`<p class="footnote">For the in-page PDF renderer, open the online demo or use Start Demo.command.</p><iframe class="pdf-preview" src="${previewObjectUrl}" title="PDF preview"></iframe>`;return}const renderer=await import('./pdf.min.mjs');renderer.GlobalWorkerOptions.workerSrc=new URL('./pdf.worker.min.mjs',location.href).href;pdf=await renderer.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;if(!container.isConnected)return;container.innerHTML='';const max=Math.min(pdf.numPages,30);for(let n=1;n<=max;n++){if(!container.isConnected)break;const page=await pdf.getPage(n),base=page.getViewport({scale:1}),width=Math.max(240,container.clientWidth),scale=width/base.width,ratio=Math.min(devicePixelRatio||1,2),viewport=page.getViewport({scale:scale*ratio}),sheet=document.createElement('div'),canvas=document.createElement('canvas');sheet.className='pdf-sheet';canvas.width=Math.floor(viewport.width);canvas.height=Math.floor(viewport.height);canvas.style.width='100%';canvas.style.height='auto';canvas.setAttribute('role','img');canvas.setAttribute('aria-label','PDF page '+n+' of '+pdf.numPages);sheet.append(canvas);container.append(sheet);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const text=await page.getTextContent(),details=document.createElement('details'),summary=document.createElement('summary'),content=document.createElement('p');summary.textContent='Page '+n+' · Text version';content.textContent=text.items.map(t=>t.str).join(' ');details.className='pdf-text';details.append(summary,content);sheet.append(details)}if(pdf.numPages>max){let note=document.createElement('p');note.className='footnote';note.textContent='Showing the first 30 pages. Download to read the full document.';container.append(note)}}catch(error){if(container.isConnected){container.innerHTML='<div class="preview-empty"><h3>Unable to render this PDF</h3><p class="muted">The file may be password-protected or use an unsupported format. Download it to open the original.</p></div>'}}finally{if(pdf)await pdf.destroy()}}
async function renderFilePreview(){destroyFilePreview();let f=data.files.find(f=>f.id===profilePreviewId);if(!f)return;let panel=document.createElement('aside');panel.className='file-preview-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Material preview');panel.innerHTML=`<div class="file-preview-header"><div><small>${esc(f.type)} / ${esc(f.category)}</small><h2>${esc(f.name)}</h2></div><button class="close" aria-label="Close material preview">×</button></div><div class="file-preview-body">${f.uploaded?'<div class="preview-loading">Opening local file…</div>':sampleResume(f)}</div>`;document.body.append(panel);panel.querySelector('.close').onclick=closeFilePreview;panel.querySelector('.close').focus();if(!f.uploaded)return;try{let file=f.hasBlob?await localFileStore('get',f.id):null;if(!panel.isConnected||profilePreviewId!==f.id)return;let body=panel.querySelector('.file-preview-body');if(!file){body.innerHTML=`<div class="preview-empty"><h3>Choose this file to preview it</h3><p class="muted">${esc(f.filename||f.name)}</p><small>This older entry saved the file name only. Select the original file once to enable browser-local preview.</small><label class="field sectiongap">Original file<input type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.png,.jpg,.jpeg" id="restore-preview-file"></label></div>`;body.querySelector('input').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{await localFileStore('put',f.id,file);f.hasBlob=true;f.filename=file.name;f.mime=file.type;save();renderFilePreview()}catch{toast('File storage is unavailable in this browser')}};return}previewObjectUrl=URL.createObjectURL(file);let isPdf=file.type==='application/pdf'||/\.pdf$/i.test(file.name),isImage=/^image\/(png|jpeg|webp)$/.test(file.type);body.innerHTML=`<div class="local-file-note"><span class="pill attention">LOCAL FILE</span><small>Only stored in this browser</small><a href="${previewObjectUrl}" download="${esc(file.name)}">Download ↗</a></div>${isPdf?`<div class="pdf-pages" aria-label="${esc(f.name)} PDF preview"><div class="preview-loading">Rendering PDF…</div></div>`:isImage?`<img class="image-preview" src="${previewObjectUrl}" alt="${esc(f.name)}">`:`<div class="preview-empty"><h3>Preview unavailable for this format</h3><p>${esc(file.name)}</p><p class="muted">Use a PDF or image for an inline preview, or download to open the original file.</p></div>`}`;if(isPdf)renderPdfPages(file,body.querySelector('.pdf-pages'))}catch{if(panel.isConnected)panel.querySelector('.file-preview-body').innerHTML='<div class="preview-empty">Cannot open browser-local file storage.</div>'}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!e.defaultPrevented&&profilePreviewId)closeFilePreview()});
const newsItems=[{title:'Figma: give AI agents your design-system context',date:'2026-10-23',source:'Figma',topics:['Design','AI'],url:'https://www.figma.com/blog/how-to-put-your-design-system-to-work-with-the-figma-agent/',apply:'Write three design rules from one portfolio project and test them in an AI prototype.'},{title:'NUS: a touchscreen woven into clothing',date:'2026-10-22',source:'NUS News',topics:['Research','Design'],url:'https://news.nus.edu.sg/worlds-first-touchscreen-in-garment',apply:'Sketch one wearable interaction for a user need you have already researched.'},{title:'Design systems for an AI-assisted workflow',date:'2026-10-20',source:'thoughtbot',topics:['Design','AI'],url:'https://thoughtbot.com/blog/design-systems-in-an-ai-era',apply:'Document one reusable component and the reason behind its behaviour in your portfolio.'},{title:'Figma opens code layers to teams',date:'2026-10-15',source:'Figma',topics:['Product','Design'],url:'https://www.figma.com/blog/design-together-with-code-layers/',apply:'Turn one flow from a portfolio project into a small working prototype.'}];
function industryNews(){let list=newsItems.map((n,i)=>({...n,id:i})).filter(n=>n.topics.some(t=>data.newsInterests.includes(t))).slice(0,2);return `<section class="card news-card"><div class="row between"><h3>Industry news</h3><button class="quiet" data-action="news-interests">Following</button></div><small>${esc(data.newsInterests.join(' · '))}</small>${list.map(n=>`<article class="news-item"><small>${n.source} · ${n.date.slice(5).replace('-','/')}</small><a href="${n.url}" target="_blank" rel="noopener noreferrer"><h4>${n.title} ↗</h4></a><p><span class="news-apply-label">Try</span> ${n.apply}</p><button class="quiet" data-news-task="${n.id}">+ Add to tasks</button></article>`).join('')||'<p class="footnote">No stories for these interests yet.</p>'}<small class="news-snapshot">Curated 26 Oct 2026 · Not a live feed</small></section>`}
function chooseNewsInterests(){formDialog('Following',`<div class="interest-options">${['Design','Research','Product','AI'].map(t=>`<label><input type="checkbox" name="topic" value="${t}" ${data.newsInterests.includes(t)?'checked':''}>${t}</label>`).join('')}</div>`,form=>{let topics=form.getAll('topic');if(!topics.length)return 'Choose at least one interest.';data.newsInterests=topics})}
function addCustomTask(title){if(data.customTasks.some(t=>t.title===title)){toast('Already in your tasks');return}data.customTasks.push({id:'task-'+Date.now(),title});save();toast('Added to Today')}
function deleteJob(id){let index=data.jobs.findIndex(j=>j.id===id);if(index<0)return;let job=data.jobs.splice(index,1)[0];if(selected===id){selected=null;document.querySelector('.drawer')?.remove()}save();render();clearTimeout(toastTimer);let host=$('#toast');host.textContent=job.company+' job deleted. ';let undo=document.createElement('button');undo.textContent='Undo';undo.className='toast-undo';undo.onclick=()=>{if(!data.jobs.some(j=>j.id===job.id)){if(!cats.includes(job.category))job.category=cats[0];data.jobs.splice(Math.min(index,data.jobs.length),0,job);save();render()}toast('Job restored')};host.append(undo);host.classList.add('show');toastTimer=setTimeout(()=>host.classList.remove('show'),6500)}
function chooseExperiences(){let it=activeInterview();formDialog('Relevant experiences',`<div class="interest-options">${stories.map((e,i)=>`<label><input type="checkbox" name="experience" value="${i}" ${it.stories.includes(i)?'checked':''}><span>${esc(e.title)}</span></label>`).join('')}</div>`,form=>{it.stories=form.getAll('experience').map(Number)})}
function addExperience(){let it=activeInterview();formDialog('Add experience',`<label class="field">Title<input type="text" name="title" maxlength="100" required></label><label class="field">Your experience<textarea name="text" maxlength="5000" required placeholder="What happened, your role, and what you did…"></textarea></label>`,form=>{let title=form.get('title').trim(),text=form.get('text').trim();if(!title||!text)return 'Add a title and your experience.';if(!it.extraStories)it.extraStories=[];it.extraStories.push({id:'experience-'+Date.now(),title,text})})}
function askAboutExperience(text){let it=activeInterview();chatContext={text:text.slice(0,5000),company:it.company,title:it.title};chatDraft='How can I explain this for the role?';hideSelectionAsk();toggleChat(true)}
function hideSelectionAsk(){document.querySelector('#selection-ask')?.remove();selectedInterviewText=''}
function showSelectionAsk(event){if(location.hash!=='#interviews'||event?.target?.closest?.('#selection-ask')||chatOpen)return;let target=event?.target,selection=window.getSelection(),text='',rect;if(target?.matches?.('#interview-notes,#interview-review')&&target.selectionEnd>target.selectionStart){text=target.value.slice(target.selectionStart,target.selectionEnd);rect=target.getBoundingClientRect()}else if(selection&&!selection.isCollapsed&&selection.rangeCount){let anchor=selection.anchorNode?.nodeType===1?selection.anchorNode:selection.anchorNode?.parentElement,focus=selection.focusNode?.nodeType===1?selection.focusNode:selection.focusNode?.parentElement;if(anchor?.closest?.('[data-interview-selectable]')&&focus?.closest?.('[data-interview-selectable]')){text=selection.toString();rect=selection.getRangeAt(0).getBoundingClientRect()}}if(text.trim().length<2){hideSelectionAsk();return}document.querySelector('#selection-ask')?.remove();selectedInterviewText=text.trim().slice(0,5000);let button=document.createElement('button');button.id='selection-ask';button.className='selection-ask';button.textContent='✦ Ask AI';button.style.left=Math.max(12,Math.min(rect.left,innerWidth-130))+'px';button.style.top=Math.max(92,Math.min(rect.bottom+8,innerHeight-60))+'px';button.onpointerdown=e=>e.preventDefault();button.onclick=()=>askAboutExperience(selectedInterviewText);document.body.append(button)}
document.addEventListener('pointerup',showSelectionAsk);document.addEventListener('keyup',e=>{if(e.key==='Escape')hideSelectionAsk();else if(e.key==='Shift'||e.key.startsWith('Arrow'))showSelectionAsk(e)});document.addEventListener('scroll',()=>hideSelectionAsk(),true);
function toggleAccountMenu(){let old=document.querySelector('.account-menu');if(old){old.remove();accountMenuOpen=false;$('#account-toggle')?.setAttribute('aria-expanded','false');return}let anchor=$('#account-toggle'),r=anchor.getBoundingClientRect(),menu=document.createElement('div');menu.className='account-menu';menu.setAttribute('role','menu');menu.innerHTML='<small>Demo account</small><button role="menuitem" id="logout-demo">Log out</button>';menu.style.top=r.bottom+8+'px';menu.style.right=Math.max(12,innerWidth-r.right)+'px';document.body.append(menu);accountMenuOpen=true;anchor.setAttribute('aria-expanded','true');menu.querySelector('button').onclick=()=>{demoLoggedOut=true;sessionStorage.setItem('nus-career-logged-out','1');menu.remove();accountMenuOpen=false;chatMessages=[];chatDraft='';chatContext=null;chatOpen=false;document.querySelector('#career-chat')?.remove();document.querySelector('.calendar-popover')?.remove();document.querySelector('.drawer')?.remove();hideSelectionAsk();profilePreviewId=null;destroyFilePreview();render();scrollTo(0,0)}}
document.addEventListener('pointerdown',e=>{let menu=document.querySelector('.account-menu');if(menu&&!menu.contains(e.target)&&!e.target.closest('#account-toggle')){menu.remove();accountMenuOpen=false;$('#account-toggle')?.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.account-menu')?.remove();accountMenuOpen=false;$('#account-toggle')?.setAttribute('aria-expanded','false')}});
function renderLoggedOut(){document.querySelector('.account-menu')?.remove();$('#header').innerHTML='<a class="brand" href="#today">NUS Career Space</a>';$('#app').className='shell';$('#app').innerHTML='<section class="card session-screen"><span class="pill attention">DEMO SESSION</span><h1>You’re logged out</h1><p class="muted">Your saved demo data remains in this browser.</p><button class="primary" id="continue-demo">Continue demo →</button><small>No school account is connected.</small></section>';$('#continue-demo').onclick=()=>{demoLoggedOut=false;sessionStorage.removeItem('nus-career-logged-out');render()}}
normaliseData();
window.addEventListener('hashchange',()=>{hideSelectionAsk();if(location.hash!=='#profile'){profilePreviewId=null;destroyFilePreview()}document.querySelector('.drawer')?.remove();document.querySelector('.calendar-popover')?.remove();if(location.hash!=='#jobs')selected=null;render();scrollTo(0,0)});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.calendar-popover')?.remove();if(e.key==='Escape'&&selected){selected=null;document.querySelector('.drawer')?.remove();render()}});render();
